/**
 * PREP - Buscar Material
 *
 * Objetivo:
 * - preservar integralmente o item recebido;
 * - identificar a famÃ­lia provÃ¡vel;
 * - normalizar abreviaÃ§Ãµes, unidades e caracterÃ­sticas tÃ©cnicas;
 * - gerar uma chave estrita para busca no MaterialOficial;
 * - gerar uma chave-base para futura busca alternativa;
 * - nÃ£o inventar caracterÃ­sticas ausentes.
 */

const entrada = $json || {};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function removerDecimaisZero(valor) {
  return valor.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function escaparOData(valor) {
  return texto(valor).replace(/'/g, "''");
}

function aplicarMapaPorPalavra(valor, mapa) {
  let resultado = valor;

  const termos = Object.keys(mapa)
    .sort((a, b) => b.length - a.length);

  for (const termo of termos) {
    const substituto = mapa[termo];

    const termoEscapado = termo.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

    resultado = resultado.replace(
      new RegExp(`\\b${termoEscapado}\\b`, 'g'),
      substituto
    );
  }

  return resultado;
}

function removerPalavras(valor, palavras) {
  let resultado = valor;

  for (const palavra of palavras) {
    resultado = resultado.replace(
      new RegExp(`\\b${palavra}\\b`, 'g'),
      ' '
    );
  }

  return resultado;
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

/* -------------------------------------------------------------------------- */
/* DicionÃ¡rios                                                                */
/* -------------------------------------------------------------------------- */

const sinonimosGlobais = {
  PÃ‡: 'UN',
  PC: 'UN',
  PCA: 'UN',
  PECA: 'UN',
  UND: 'UN',
  UNID: 'UN',
  UNIDADE: 'UN',

  METRO: 'M',
  METROS: 'M',

  QTD: 'QUANTIDADE',

  ELETR: 'ELETRICO',
  ELET: 'ELETRICO',

  TRIF: 'TRIFASICO',
  MONOF: 'MONOFASICO',

  EXT: 'EXTERNO',
  INT: 'INTERNO'
};

const sinonimosPorFamilia = {
  CABOS: {
    CU: 'COBRE',
    COB: 'COBRE',
    AL: 'ALUMINIO',
    ALUM: 'ALUMINIO',

    FLEX: 'FLEXIVEL',
    FLEXIV: 'FLEXIVEL',

    RIG: 'RIGIDO',

    COND: 'CONDUTOR',

    XLPE: 'XLPE',
    EPR: 'EPR',
    PVC: 'PVC'
  },

  DISJUNTORES: {
    DISJ: 'DISJUNTOR',
    DJ: 'DISJUNTOR',

    MONOP: 'MONOPOLAR',
    UNIP: 'MONOPOLAR',
    UNIPOLAR: 'MONOPOLAR',

    BIP: 'BIPOLAR',
    '2P': 'BIPOLAR',

    TRIP: 'TRIPOLAR',
    '3P': 'TRIPOLAR',

    TETRAP: 'TETRAPOLAR',
    '4P': 'TETRAPOLAR',

    CM: 'CAIXA MOLDADA',
    MCCB: 'CAIXA MOLDADA',
    MCB: 'MINIDISJUNTOR'
  },

  ELETRODUTOS: {
    ELETROD: 'ELETRODUTO',
    ELETRODUTO: 'ELETRODUTO',

    CORR: 'CORRUGADO',

    GALV: 'GALVANIZADO',

    PEAD: 'PEAD',
    PVC: 'PVC'
  },

  POSTES: {
    CONC: 'CONCRETO',

    DT: 'DUPLO T',
    DUPLOT: 'DUPLO T',

    CIRC: 'CIRCULAR'
  },

  TRANSFORMADORES: {
    TRAFO: 'TRANSFORMADOR',
    TRANSF: 'TRANSFORMADOR',

    OLEO: 'OLEO',
    SECO: 'SECO'
  },

  CONECTORES: {
    CONECT: 'CONECTOR',
    CONEC: 'CONECTOR',

    PERF: 'PERFURANTE',

    COMP: 'COMPRESSAO'
  },

  TERMINAIS: {
    TERM: 'TERMINAL',

    COMP: 'COMPRESSAO'
  },

  ISOLADORES: {
    ISOL: 'ISOLADOR',

    POLIM: 'POLIMERICO',

    PORC: 'PORCELANA'
  },

  BARRAMENTOS: {
    BARR: 'BARRAMENTO',

    CU: 'COBRE',
    AL: 'ALUMINIO'
  }
};

/*
 * Removemos apenas palavras de ligaÃ§Ã£o.
 * NÃ£o remover â€œTIPOâ€, â€œCLASSEâ€, â€œCURVAâ€, â€œEXTERNOâ€ ou â€œINTERNOâ€,
 * pois podem diferenciar materiais.
 */
const palavrasLigacao = [
  'DE',
  'DA',
  'DO',
  'DAS',
  'DOS',
  'EM',
  'PARA'
];

/* -------------------------------------------------------------------------- */
/* IdentificaÃ§Ã£o de famÃ­lia                                                   */
/* -------------------------------------------------------------------------- */

function identificarFamilia(valor) {
  const descricao = limparEspacos(valor);

  if (
    /\bCABO\b/.test(descricao) ||
    /\bCONDUTOR\b/.test(descricao)
  ) {
    return 'CABOS';
  }

  if (
    /\bDISJUNTOR\b/.test(descricao) ||
    /\bDISJ\b/.test(descricao) ||
    /\bMCCB\b/.test(descricao) ||
    /\bMCB\b/.test(descricao)
  ) {
    return 'DISJUNTORES';
  }

  if (
    /\bELETRODUTO\b/.test(descricao) ||
    /\bELETROD\b/.test(descricao)
  ) {
    return 'ELETRODUTOS';
  }

  if (/\bPOSTE\b/.test(descricao)) {
    return 'POSTES';
  }

  if (
    /\bTRANSFORMADOR\b/.test(descricao) ||
    /\bTRAFO\b/.test(descricao) ||
    /\bTRANSF\b/.test(descricao)
  ) {
    return 'TRANSFORMADORES';
  }

  if (/\bCONECTOR\b|\bCONECT\b|\bCONEC\b/.test(descricao)) {
    return 'CONECTORES';
  }

  if (/\bTERMINAL\b|\bTERM\b/.test(descricao)) {
    return 'TERMINAIS';
  }

  if (/\bISOLADOR\b|\bISOL\b/.test(descricao)) {
    return 'ISOLADORES';
  }

  if (/\bBARRAMENTO\b|\bBARR\b/.test(descricao)) {
    return 'BARRAMENTOS';
  }

  if (
    /\bCHAVE SECCIONADORA\b/.test(descricao) ||
    /\bSECCIONADORA\b/.test(descricao)
  ) {
    return 'CHAVES_SECCIONADORAS';
  }

  if (
    /\bCAIXA PASSAGEM\b/.test(descricao) ||
    /\bCAIXA DE PASSAGEM\b/.test(descricao)
  ) {
    return 'CAIXAS_PASSAGEM';
  }

  if (
  /\bBANCO CAPAC\b/.test(descricao) ||
  /\bBANCO DE CAPACITORES?\b/.test(descricao) ||
  /\bCAPACITORES?\b/.test(descricao)
) {
  return 'CAPACITORES_E_BANCOS';
}

  return 'OUTROS';
}

/* -------------------------------------------------------------------------- */
/* PadronizaÃ§Ã£o tÃ©cnica                                                       */
/* -------------------------------------------------------------------------- */

function padronizarUnidades(valor) {
  let resultado = valor;

  // SeÃ§Ã£o de condutor
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\s*[Â²2]\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MM2\b/g, '$1 MM2')
    .replace(/(\d+(?:[.,]\d+)?)\s*MMQ\b/g, '$1 MM2');

  // DiÃ¢metro e dimensÃµes lineares
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*MM\b/g, '$1 MM')
    .replace(/(\d+(?:[.,]\d+)?)\s*CM\b/g, '$1 CM')
    .replace(/(\d+(?:[.,]\d+)?)\s*M\b/g, '$1 M');

  // Corrente
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*AMPERES?\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*AMP\b/g, '$1 A')
    .replace(/(\d+(?:[.,]\d+)?)\s*A\b/g, '$1 A');

  // TensÃ£o
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KV\b/g, '$1 KV')
    .replace(/(\d+(?:[.,]\d+)?)\s*V\b/g, '$1 V');

  // PotÃªncia ativa, aparente e reativa
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KVAR\b/g, '$1 KVAR')
    .replace(/(\d+(?:[.,]\d+)?)\s*KVA\b/g, '$1 KVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*MVA\b/g, '$1 MVA')
    .replace(/(\d+(?:[.,]\d+)?)\s*KW\b/g, '$1 KW')
    .replace(/(\d+(?:[.,]\d+)?)\s*MW\b/g, '$1 MW');

// ForÃ§a / carga mecÃ¢nica
resultado = resultado
  .replace(/(\d+(?:[.,]\d+)?)\s*DAN\b/g, '$1 DAN');

  // Capacidade de interrupÃ§Ã£o
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*KA\b/g, '$1 KA');

  // PotÃªncia mecÃ¢nica
  resultado = resultado
    .replace(/(\d+(?:[.,]\d+)?)\s*CV\b/g, '$1 CV')
    .replace(/(\d+(?:[.,]\d+)?)\s*HP\b/g, '$1 HP');

  return resultado;
}

function padronizarNumeros(valor) {
  return valor.replace(
    /(\d),(\d)/g,
    '$1.$2'
  );
}

function padronizarTensoesDeCabo(valor, familia) {
  if (familia !== 'CABOS') {
    return valor;
  }

  let resultado = valor;

  /*
   * Normaliza somente equivalÃªncias explicitamente
   * informadas na descriÃ§Ã£o.
   * NÃ£o completa classes de tensÃ£o ausentes.
   */
  resultado = resultado
    .replace(
      /\b0[.,]6\s*[\/\\-]\s*1\s*KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b0\s+6\s+1\s+KV\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b600\s*[\/\\-]\s*1000\s*V\b/g,
      '0.6/1 KV'
    )
    .replace(
      /\b450\s*[\/\\-]\s*750\s*V\b/g,
      '450/750 V'
    );

  return resultado;
}

function padronizarPolos(valor, familia) {
  if (familia !== 'DISJUNTORES') {
    return valor;
  }

  return valor
    .replace(/\b1\s*P\b/g, 'MONOPOLAR')
    .replace(/\b2\s*P\b/g, 'BIPOLAR')
    .replace(/\b3\s*P\b/g, 'TRIPOLAR')
    .replace(/\b4\s*P\b/g, 'TETRAPOLAR');
}

function padronizarDimensoes(valor) {
  return valor
    .replace(
      /(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 MM'
    )
    .replace(
      /(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*[XÃ—]\s*(\d+(?:\.\d+)?)\s*MM\b/g,
      '$1 X $2 X $3 MM'
    );
}

/* -------------------------------------------------------------------------- */
/* GeraÃ§Ã£o das chaves                                                         */
/* -------------------------------------------------------------------------- */

function normalizarDescricao(valor) {
  let resultado = removerAcentos(valor)
    .toUpperCase()
    .replace(/Â²/g, '2')
    .replace(/[â€œâ€"'`Â´]/g, ' ')
    .replace(/[(){}\[\]]/g, ' ')
    .replace(/[;:]/g, ' ')
    .replace(/â€“|â€”/g, '-');

  resultado = limparEspacos(resultado);

  const familia = identificarFamilia(resultado);

  resultado = aplicarMapaPorPalavra(
    resultado,
    sinonimosGlobais
  );

  const regrasFamilia =
    sinonimosPorFamilia[familia] || {};

  resultado = aplicarMapaPorPalavra(
    resultado,
    regrasFamilia
  );

  resultado = padronizarNumeros(resultado);
  resultado = padronizarUnidades(resultado);
  // Remove apenas casas decimais zero apÃ³s separar/padronizar unidades.
  resultado = removerDecimaisZero(resultado);
  resultado = padronizarTensoesDeCabo(
    resultado,
    familia
  );
  resultado = padronizarPolos(
    resultado,
    familia
  );
  resultado = padronizarDimensoes(resultado);

  /*
   * Preserva "/" em tensÃµes como 0.6/1 KV e cÃ³digos como 12/600.
   * Preserva "." para valores decimais.
   */
  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

  resultado = removerPalavras(
    resultado,
    palavrasLigacao
  );

  resultado = limparEspacos(resultado);

  return {
    descricao_normalizada: resultado,
    familia
  };
}

function gerarChaveBase(chaveEstrita, familia) {
  let resultado = chaveEstrita;

  /*
   * A chave-base remove poucos atributos opcionais.
   * Ela nÃ£o deve ser usada para aprovaÃ§Ã£o automÃ¡tica.
   * Serve apenas para uma futura busca de candidatos.
   */
  if (familia === 'CABOS') {
    resultado = resultado
      .replace(/\b0\.6\/1 KV\b/g, ' ')
      .replace(/\b450\/750 V\b/g, ' ');
  }

  resultado = resultado
    .replace(/\bPRETO\b/g, ' ')
    .replace(/\bAZUL\b/g, ' ')
    .replace(/\bVERMELHO\b/g, ' ')
    .replace(/\bVERDE\b/g, ' ')
    .replace(/\bAMARELO\b/g, ' ')
    .replace(/\bBRANCO\b/g, ' ');

  return limparEspacos(resultado);
}

/* -------------------------------------------------------------------------- */
/* ValidaÃ§Ã£o de entrada                                                       */
/* -------------------------------------------------------------------------- */

const codigoItem = texto(entrada.codigo_item);

const descricaoOriginal =
  texto(entrada.descricao_original);

if (!codigoItem) {
  throw new Error(
    'codigo_item nÃ£o recebido no workflow de normalizaÃ§Ã£o.'
  );
}

if (!descricaoOriginal) {
  return {
    json: {
      ...entrada,

      chave_normalizada_busca: null,
      chave_normalizada_base: null,
      familia_normalizada: null,

      material_sugerido: null,
      material_oficial_id: null,
      material_encontrado: false,
      motivo_material: 'DESCRICAO_AUSENTE'
    }
  };
}

/* -------------------------------------------------------------------------- */
/* Processamento                                                               */
/* -------------------------------------------------------------------------- */

const normalizacao =
  normalizarDescricao(descricaoOriginal);

const chaveEstrita =
  normalizacao.descricao_normalizada;

const chaveBase =
  gerarChaveBase(
    chaveEstrita,
    normalizacao.familia
  );

return {
  json: {
    ...entrada,

    normalizacao_material: {
      ...(entrada.normalizacao_material || {}),

      descricao_original:
        descricaoOriginal,

      descricao_normalizada:
        chaveEstrita,

      familia_sugerida:
        normalizacao.familia,

      chave_base:
        chaveBase
    },

    familia_normalizada:
      normalizacao.familia,

    chave_normalizada_busca:
      chaveEstrita,

    chave_normalizada_base:
      chaveBase,

    chave_normalizada_odata:
      escaparOData(chaveEstrita)
  }
};

const itemOriginal =
  $('PREP - Normalizar DescriÃ§Ã£o').item.json || {};

const respostaGraph = $json || {};

const registros =
  Array.isArray(respostaGraph.value)
    ? respostaGraph.value
    : [];

const chaveBusca =
  String(
    itemOriginal.chave_normalizada_busca || ''
  ).trim();

const registrosValidos =
  registros.filter((registro) =>
    String(
      registro?.fields?.Nome_Normalizado || ''
    ).trim() === chaveBusca &&
    String(registro?.fields?.Status || '').trim().toUpperCase() === 'ATIVO'
  );

const houveColisao =
  registrosValidos.length > 1;

const materialEncontrado =
  registrosValidos.length === 1
    ? registrosValidos[0]
    : null;

const fieldsMaterial =
  materialEncontrado?.fields || {};

const materialId =
  materialEncontrado?.id
    ? Number(materialEncontrado.id)
    : null;

const codigoMaterial =
  String(
    fieldsMaterial.Codigo_Neoenergia ||
    fieldsMaterial.CodMaterial ||
    ''
  ).trim();

const nomeMaterial =
  String(
    fieldsMaterial.Material ||
    fieldsMaterial.Descricao_Neoenergia ||
    fieldsMaterial.Nome_Normalizado ||
    fieldsMaterial.Title ||
    ''
  ).trim();

const encontrou =
  Boolean(materialEncontrado && materialId);

/*
 * IMPORTANTE:
 * Este workflow apenas SUGERE um Material Oficial.
 * Nunca aprova automaticamente o material do item.
 */
return {
  json: {
    ...itemOriginal,

    material_sugerido:
      encontrou
        ? (nomeMaterial || null)
        : null,

    material_oficial_id:
      encontrou
        ? materialId
        : null,

    codigo_neoenergia_sugerido:
      encontrou
        ? (codigoMaterial || null)
        : null,

    material_encontrado:
      encontrou,

    motivo_material:
      encontrou
        ? 'MATCH_EXATO_ATIVO'
        : houveColisao
          ? 'COLISAO_MATCH_EXATO'
          : 'SEM_MATCH_EXATO_ATIVO',

    status_associacao:
      encontrou ? 'EXATO' : 'SEM_ASSOCIACAO',

    estrategia_matching:
      'DESCRICAO_NORMALIZADA_EXATA',

    material_oficial:
      encontrou
        ? {
            id: materialId,

            codigo_neoenergia:
              codigoMaterial || null,

            material:
              nomeMaterial || null,

            nome_normalizado:
              fieldsMaterial.Nome_Normalizado || null,

            chave_normalizada:
              fieldsMaterial.Chave_Normalizada || null,

            familia:
              fieldsMaterial.Familia || null,

            subfamilia:
              fieldsMaterial.Subfamilia || null,

            categoria:
              fieldsMaterial.Categoria || null,

            unidade_padrao:
              fieldsMaterial.Unidade_Padrao || null,

            origem_catalogo:
              fieldsMaterial.Origem_Catalogo || null,

            status:
              fieldsMaterial.Status || null
          }
        : null
  }
};

const entrada = $json || {};

const descricao =
  String(
    entrada.chave_normalizada_busca ||
    entrada.normalizacao_material?.descricao_normalizada ||
    ''
  ).trim();

const familiaNormalizada =
  entrada.familia_normalizada ||
  entrada.normalizacao_material?.familia_sugerida ||
  'OUTROS';

/*
 * Mapeia nossa taxonomia interna
 * para a nomenclatura usada no catÃ¡logo Neoenergia.
 */
/*
 * A famÃ­lia jÃ¡ utiliza a taxonomia canÃ´nica
 * cadastrada em Materiais_Oficiais.
 */
const familiaCatalogo =
  String(familiaNormalizada || 'OUTROS')
    .trim()
    .toUpperCase();

function extrairAtributosTecnicos(texto) {
  const encontrados = [];

  const regex =
    /\b(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|A|KA|KVA|MVA|KW|MW|CV|HP|DAN)\b/g;

  let match;

  while ((match = regex.exec(texto)) !== null) {
    encontrados.push({
      valor: Number(match[1]),
      unidade: match[2],
      token: `${match[1]} ${match[2]}`
    });
  }

  return encontrados;
}

function extrairTokensTextuais(texto) {
  const unidades = new Set([
    'KV', 'V', 'MM2', 'MM', 'CM', 'M',
    'A', 'KA', 'KVA', 'MVA', 'KW',
    'MW', 'CV', 'HP', 'DAN'
  ]);

  return [
    ...new Set(
      texto
        .split(/\s+/)
        .map(t => t.trim())
        .filter(Boolean)
        .filter(t => !/^\d+(?:\.\d+)?$/.test(t))
        .filter(t => !unidades.has(t))
    )
  ];
}

const atributosTecnicos =
  extrairAtributosTecnicos(descricao);

const tokensTextuais =
  extrairTokensTextuais(descricao);

return {
  json: {
    ...entrada,

    busca_candidatos: {
      familia_normalizada: familiaNormalizada,
      familia_catalogo: familiaCatalogo,
      descricao_normalizada: descricao,
      atributos_tecnicos: atributosTecnicos,
      tokens_textuais: tokensTextuais,
      estrategia: 'BUSCA_CANDIDATOS'
    }
  }
};

const entrada =
  $('PREP - Busca por Candidatos').item.json || {};

const respostaGraph = $json || {};

const candidatos =
  Array.isArray(respostaGraph.value)
    ? respostaGraph.value
    : [];

const busca =
  entrada.busca_candidatos || {};

const atributosEntrada =
  Array.isArray(busca.atributos_tecnicos)
    ? busca.atributos_tecnicos
    : [];

const tokensEntrada =
  Array.isArray(busca.tokens_textuais)
    ? busca.tokens_textuais
    : [];

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

function texto(valor) {
  return String(valor ?? '').trim();
}

function removerAcentos(valor) {
  return texto(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function limparEspacos(valor) {
  return texto(valor)
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizarTexto(valor) {
  let resultado =
    removerAcentos(valor)
      .toUpperCase()
      .replace(/Â²/g, '2')
      .replace(/(\d),(\d)/g, '$1.$2');

  /*
   * AbreviaÃ§Ãµes importantes para o catÃ¡logo atual.
   */
  resultado = resultado
    .replace(/\bPOLIM\b/g, 'POLIMERICO')
    .replace(/\bPORC\b/g, 'PORCELANA')
    .replace(/\bPORCE\b/g, 'PORCELANA')
    .replace(/\bISOL\b/g, 'ISOLADOR');

  /*
   * Separa nÃºmeros das principais unidades tÃ©cnicas.
   */
  resultado = resultado.replace(
    /(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|KA|KVA|MVA|KW|MW|CV|HP|DAN|KN|A)\b/g,
    '$1 $2'
  );

  /*
   * 15.0 â†’ 15
   */
  resultado = resultado.replace(
    /\b(\d+)\.0+\b/g,
    '$1'
  );

  resultado = resultado
    .replace(/[^A-Z0-9./]+/g, ' ');

  return limparEspacos(resultado);
}

function extrairAtributosTecnicos(valor) {
  const resultado = [];

  const descricao =
    normalizarTexto(valor);

  const regex =
    /\b(\d+(?:\.\d+)?)\s*(KV|V|MM2|MM|CM|M|KA|KVA|MVA|KW|MW|CV|HP|DAN|KN|A)\b/g;

  let match;

  while ((match = regex.exec(descricao)) !== null) {
    resultado.push({
      valor: Number(match[1]),
      unidade: match[2],
      token: `${Number(match[1])} ${match[2]}`
    });
  }

  return resultado;
}

function extrairTokensTextuais(valor) {
  const descricao =
    normalizarTexto(valor);

  const unidades = new Set([
    'KV',
    'V',
    'MM2',
    'MM',
    'CM',
    'M',
    'A',
    'KA',
    'KVA',
    'MVA',
    'KW',
    'MW',
    'CV',
    'HP',
    'DAN',
    'KN'
  ]);

  return [
    ...new Set(
      descricao
        .split(/\s+/)
        .filter(Boolean)
        .filter(
          token =>
            !/^\d+(?:\.\d+)?$/.test(token)
        )
        .filter(
          token =>
            !unidades.has(token)
        )
    )
  ];
}

function mesmoNumero(a, b) {
  return (
    Math.abs(
      Number(a) - Number(b)
    ) < 0.000001
  );
}

/*
 * CanonizaÃ§Ã£o de termos equivalentes.
 *
 * Objetivo:
 * CAPAC / CAPACITOR / CAPACITORES
 * devem representar o mesmo conceito.
 *
 * NÃ£o estamos reduzindo o threshold.
 * Apenas tratando abreviaÃ§Ãµes conhecidas.
 */
function canonicalizarToken(token) {
  const t =
    normalizarTexto(token);

  const mapa = {
    CAPAC: 'CAPACITOR',
    CAPACITOR: 'CAPACITOR',
    CAPACITORES: 'CAPACITOR'
  };

  return mapa[t] || t;
}

/*
 * Tokens canÃ´nicos da entrada.
 */
const tokensEntradaCanonicos = [
  ...new Set(
    tokensEntrada.map(
      canonicalizarToken
    )
  )
];

/* -------------------------------------------------------------------------- */
/* AvaliaÃ§Ã£o                                                                  */
/* -------------------------------------------------------------------------- */

const avaliados =
  candidatos.map(candidato => {

    const fields =
      candidato?.fields || {};

    /*
     * Nome_Normalizado Ã© nossa principal fonte
     * para comparaÃ§Ã£o tÃ©cnica.
     */
    const descricao =
      fields.Nome_Normalizado ||
      fields.Material ||
      fields.Title ||
      '';

    const descricaoNormalizada =
      normalizarTexto(descricao);

    const atributosCandidato =
      extrairAtributosTecnicos(
        descricao
      );

    const tokensCandidato =
      extrairTokensTextuais(
        descricao
      );

    const tokensCandidatoCanonicos = [
      ...new Set(
        tokensCandidato.map(
          canonicalizarToken
        )
      )
    ];

    /*
     * Tokens da entrada que nÃ£o foram
     * encontrados no candidato.
     *
     * A comparaÃ§Ã£o jÃ¡ utiliza a forma
     * canÃ´nica.
     */
    const tokensExtrasEntrada =
      tokensEntrada.filter(token =>
        !tokensCandidatoCanonicos.includes(
          canonicalizarToken(token)
        )
      );

    /*
     * REGRA DE SEGURANÃ‡A:
     *
     * Todo atributo tÃ©cnico presente na
     * entrada precisa existir no candidato
     * com o mesmo valor e a mesma unidade.
     *
     * Exemplo:
     *
     * entrada:
     * 15 KV
     *
     * candidato:
     * 36.2 KV
     *
     * â†’ eliminado.
     */
    const atributosCompativeis =
      atributosEntrada.every(
        atributoEntrada =>
          atributosCandidato.some(
            atributoCandidato =>
              atributoEntrada.unidade ===
                atributoCandidato.unidade &&
              mesmoNumero(
                atributoEntrada.valor,
                atributoCandidato.valor
              )
          )
      );

    /*
     * Tokens textuais encontrados.
     *
     * Aqui estÃ¡ a correÃ§Ã£o principal:
     * a comparaÃ§Ã£o tambÃ©m utiliza os
     * tokens canÃ´nicos.
     */
    const tokensEncontrados =
      tokensEntrada.filter(token =>
        tokensCandidatoCanonicos.includes(
          canonicalizarToken(token)
        )
      );

    /*
     * Evita contar sinÃ´nimos equivalentes
     * mais de uma vez.
     */
    const tokensEncontradosCanonicos = [
      ...new Set(
        tokensEncontrados.map(
          canonicalizarToken
        )
      )
    ];

    /*
     * Score textual baseado nos conceitos
     * canÃ´nicos da entrada.
     */
    const scoreTextual =
      tokensEntradaCanonicos.length > 0
        ? (
            tokensEncontradosCanonicos.length /
            tokensEntradaCanonicos.length
          )
        : 0;

    /*
     * Segunda camada de matching:
     *
     * 1. atributos tÃ©cnicos = 100% compatÃ­veis;
     * 2. score textual mÃ­nimo = 60%.
     */
    const elegivel =
      atributosCompativeis &&
      scoreTextual >= 0.60;

    return {
      id:
        candidato?.id
          ? Number(candidato.id)
          : null,

      codigo_neoenergia:
        fields.Codigo_Neoenergia ||
        null,

      /*
       * Alguns registros antigos ainda nÃ£o
       * possuem Material preenchido.
       *
       * Nome_Normalizado serve como fallback.
       */
      material:
        fields.Material ||
        fields.Nome_Normalizado ||
        fields.Title ||
        null,

      nome_normalizado:
        fields.Nome_Normalizado ||
        null,

      categoria:
        fields.Categoria ||
        null,

      status:
        fields.Status ||
        null,

      descricao_avaliada:
        descricaoNormalizada,

      atributos_tecnicos:
        atributosCandidato,

      atributos_compativeis:
        atributosCompativeis,

      tokens_textuais:
        tokensCandidato,

      tokens_textuais_canonicos:
        tokensCandidatoCanonicos,

      tokens_entrada:
        tokensEntrada,

      tokens_entrada_canonicos:
        tokensEntradaCanonicos,

      tokens_encontrados:
        tokensEncontrados,

      tokens_encontrados_canonicos:
        tokensEncontradosCanonicos,

      tokens_extras_entrada:
        tokensExtrasEntrada,

      score_textual:
        Number(
          scoreTextual.toFixed(4)
        ),

      elegivel
    };
  });

/* -------------------------------------------------------------------------- */
/* Ranking                                                                    */
/* -------------------------------------------------------------------------- */

const elegiveis =
  avaliados
    .filter(
      candidato =>
        candidato.elegivel
    )
    .sort((a, b) => {

      if (
        b.score_textual !==
        a.score_textual
      ) {
        return (
          b.score_textual -
          a.score_textual
        );
      }

      return (
        (a.id || 0) -
        (b.id || 0)
      );
    });

const melhor =
  elegiveis.length > 0
    ? elegiveis[0]
    : null;

const segundo =
  elegiveis.length > 1
    ? elegiveis[1]
    : null;

/*
 * Candidato Ãºnico:
 *
 * - existe candidato elegÃ­vel;
 * - nÃ£o existe empate de score com
 *   outro candidato.
 *
 * Mesmo sendo Ãºnico, continua sendo
 * apenas uma sugestÃ£o.
 */
const candidatoUnico =
  Boolean(
    melhor &&
    (
      !segundo ||
      melhor.score_textual >
        segundo.score_textual
    )
  );

/* -------------------------------------------------------------------------- */
/* SaÃ­da                                                                      */
/* -------------------------------------------------------------------------- */

return {
  json: {
    ...entrada,

    material_sugerido:
      candidatoUnico
        ? melhor.material
        : null,

    material_oficial_id:
      candidatoUnico
        ? melhor.id
        : null,

    codigo_neoenergia_sugerido:
      candidatoUnico
        ? melhor.codigo_neoenergia
        : null,

    material_encontrado:
      candidatoUnico,

    match_automatico:
      false,

    revisao_humana_obrigatoria:
      true,

    motivo_material:
      candidatoUnico
        ? 'CANDIDATO_TECNICO_UNICO'
        : elegiveis.length > 1
          ? 'CANDIDATOS_AMBIGUOS'
          : 'SEM_CANDIDATO_COMPATIVEL',

    status_associacao:
      candidatoUnico
        ? 'SUGERIDO'
        : 'SEM_ASSOCIACAO',

    estrategia_matching:
      'CANDIDATOS_ATRIBUTOS_TECNICOS',

    avaliacao_candidatos: {
      quantidade_recebida:
        candidatos.length,

      quantidade_elegivel:
        elegiveis.length,

      melhor_candidato:
        melhor,

      candidatos_elegiveis:
        elegiveis.slice(0, 5)
    }
  }
};

